fn array_split(a: Vec<i32>) -> (Vec<i32>, Vec<i32>) {
    let n = a.len();

    // Choose a split point so that:
    // - left.len() + right.len() == n
    // - left ++ right == original order
    // - if n > 1, both parts are strictly shorter than n
    let mid = if n <= 1 { n } else { n / 2 }; // for n>1, mid in [1, n-1]

    let mut left = Vec::with_capacity(mid);
    let mut right = Vec::with_capacity(n - mid);

    for (i, x) in a.into_iter().enumerate() {
        if i < mid {
            left.push(x);
        } else {
            right.push(x);
        }
    }

    (left, right)
}